={
  "contents": [{
    "parts": [{
      "text": "You are a high-converting affiliate content writer specializing in plant equipment reviews for PlantsMag.com.

CATEGORY: {{ $json.selected.category }}
ARTICLE ANGLE: {{ $json.selected.article_angle }}
PRODUCTS TO REVIEW: {{ JSON.stringify($json.selected.products) }}
BUYER URGENCY TRIGGER: {{ $json.selected.urgency }}
SEARCH INTENT: {{ $json.selected.search_intent }}

Write a HIGH-CONVERTING comparison review article of EXACTLY 2500 words for US plant enthusiasts.

ARTICLE REQUIREMENTS:
- Title: 'Best [Category] for [Target Person] in 2026: Expert Tested & Reviewed'
- This is a PRODUCT REVIEW article — must convert readers to buyers
- Structure (Conversion-Optimized):
  * Intro (200 words): AIDA formula — Attention (problem), Interest (solution exists), Desire (best reviewed here), Action (CTA)
  * Quick Comparison Table: HTML table showing all products with pros/cons ⭐ rating
  * Section 1 — [Product 1 name] Review (350 words): Detailed review, specs, pros/cons, who it's for
  * Section 2 — [Product 2 name] Review (350 words): Detailed review, comparison with product 1
  * Section 3 — [Product 3 name] Review (350 words): Budget option review
  * Section 4 — How to Choose: buying guide (300 words)
  * Section 5 — FAQs (3 Q&As) (200 words)
  * Conclusion (200 words): Final recommendation + urgency CTA
- AFFILIATE FORMAT: [BUY: product_name | ASIN | price]
- Include EXACT price from products list
- Star ratings: ⭐ 1-5 for each product
- Conversion triggers: limited stock, price increase warning, best value badge
- Tone: Trusted expert friend giving honest advice
- SEO: Target keyword should be 'best [category] for [use case]'

Return ONLY valid JSON:
{"title": "...", "slug": "...", "meta_description": "...", "focus_keyword": "...", "winner_asin": "best product ASIN", "content": "<full HTML>"}"
    }]
  }],
  "generationConfig": { "temperature": 0.65, "maxOutputTokens": 8192 },
  "thinkingConfig": { "thinkingBudget": 2048 }
}

parameters.jsCode:
// Parse Gemini Pro response + inject high-converting affiliate CTAs
const response = $input.item.json;
const selected = $('💰 Select High-Ticket Category').item.json.selected;

let text = response?.candidates?.[0]?.content?.parts?.[0]?.text || '';
text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let article;
try {
  article = JSON.parse(text);
} catch(e) {
  const match = text.match(/\{[\s\S]*\}/);
  if (match) article = JSON.parse(match[0]);
  else throw new Error('Parse failed: ' + text.slice(0, 200));
}

// Build product map for quick lookup
const productMap = {};
for (const p of selected.products) {
  productMap[p.asin] = p;
}

// Replace [BUY: name | ASIN | price] with premium affiliate buttons
let content = article.content;
content = content.replace(/\[BUY:\s*([^|]+)\|\s*([A-Z0-9]+)\|\s*([^\]]+)\]/gi, (match, name, asin, price) => {
  const amzUrl = `https://www.amazon.com/dp/${asin.trim()}?tag=plantsmag-20`;
  const amzAeUrl = `https://www.amazon.ae/dp/${asin.trim()}?tag=plantsmag-ae-21`;
  const p = productMap[asin.trim()] || {};

  return `<div style="border:2px solid #16a34a;border-radius:10px;padding:20px;margin:20px 0;background:white;box-shadow:0 2px 8px rgba(0,0,0,0.1);">
  <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">
    <div>
      <strong style="font-size:1.1em;">${name.trim()}</strong><br>
      <span style="color:#16a34a;font-weight:bold;font-size:1.2em;">${price.trim()}</span>
      ${p.commission ? `<span style="background:#dcfce7;color:#166534;padding:2px 8px;border-radius:20px;font-size:0.85em;margin-left:8px;">${p.commission} commission</span>` : ''}
    </div>
    <div style="display:flex;gap:10px;flex-wrap:wrap;">
      <a href="${amzUrl}" target="_blank" rel="nofollow noopener" style="background:#FF9900;color:white;padding:12px 20px;text-decoration:none;border-radius:8px;font-weight:bold;white-space:nowrap;">Check on Amazon US →</a>
      <a href="${amzAeUrl}" target="_blank" rel="nofollow noopener" style="background:#00a0d6;color:white;padding:12px 20px;text-decoration:none;border-radius:8px;font-weight:bold;white-space:nowrap;">Amazon UAE 🇦🇪 →</a>
    </div>
  </div>
</div>`;
});

// Add sticky conversion banner at top
const winnerProduct = selected.products.find(p => p.asin === article.winner_asin) || selected.products[0];
const winnerUrl = `https://www.amazon.com/dp/${winnerProduct.asin}?tag=plantsmag-20`;

content = `<div style="background:linear-gradient(135deg,#14532d,#166534);color:white;padding:20px;border-radius:10px;margin-bottom:30px;">
  <p style="margin:0;font-size:0.9em;opacity:0.8;">🏆 EDITOR'S PICK 2026</p>
  <h3 style="margin:5px 0;font-size:1.3em;">${winnerProduct.name}</h3>
  <p style="margin:0 0 10px;">Our top-rated pick after expert testing — ${winnerProduct.price}</p>
  <a href="${winnerUrl}" target="_blank" rel="nofollow noopener" style="background:#FF9900;color:white;padding:12px 25px;text-decoration:none;border-radius:8px;font-weight:bold;display:inline-block;">See Current Price →</a>
</div>\n` + content;

// Affiliate disclosure
content += `\n<p style="font-size:0.85em;color:#666;border-top:1px solid #eee;padding-top:15px;margin-top:40px;"><em>Disclosure: PlantsMag participates in the Amazon Associates program. We earn a commission when you buy through our links at no extra cost to you. Our reviews are independent and honest.</em></p>`;

return {
  title: article.title,
  slug: article.slug || article.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 60),
  meta_description: article.meta_description || '',
  focus_keyword: article.focus_keyword || '',
  winner_asin: article.winner_asin || selected.products[0].asin,
  category: selected.category,
  content: content
};
